/// <summary>
/// AVA/WEN/2025/04/03        AVA_012943_ItemStatus
/// </summary>
/// <param name="args">XppPrePostArgs</param>
[PreHandlerFor(classStr(SalesLineType), methodStr(SalesLineType, initDimensionsSpecificDefaulting))]
public static void SalesLineType_Pre_initDimensionsSpecificDefaulting(XppPrePostArgs args)
{
    SalesLineType saleslineType = args.getThis();
    SalesLine salesline = saleslineType.parmSalesLine();
    InventDim inventDim = salesline.inventdim();
    WHSInventStatusId inventStatusId;

    inventStatusId = WHSAccountItemStatusDefault::find(salesline.itemid, '', ModuleInventCustVend::Invent).DefaultStatusId;

    if (inventStatusId)
    {
        inventDim.InventStatusId = inventStatusId;
        salesline.InventDimId = inventDim::findOrCreate(inventdim).inventDimId;
    }
}
